    "summary": "A structured JSON report containing a trojan classification label, a list of suspect node names, and a list of affected output ports.",
    "schema": {
      "trojan_present": "boolean",
      "confidence": "float (0.0-1.0)",
      "suspect_nodes": "array of strings",
