  },
  "metrics": [
    {
      "name": "detection_rate",
      "direction": "maximize",
      "description": "Fraction of required ground-truth findings (trojan presence, correct suspect node, correct affected output bit, correct violating condition) that the submitted report correctly captures across the SR checklist."
    },
    {
      "name": "false_positive_rate",
      "direction": "minimize",
      "description": "Fraction of reported suspect_nodes or affected_outputs that do not correspond to the true bypass path or truly-compromised bit (e.g. flagging public_out[1..3] or unrelated gates as compromised)."
    },
    {
